// Generated from src/registry/sources/control-ui/recipes/reveal.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const revealKnobs = ["--cui-reveal-hidden-opacity"] as const;
export type RevealKnobStyle = Partial<Record<(typeof revealKnobs)[number], string>>;

@layer components {
  :where([data-control-family="reveal"][data-slot="scope"]) {
    --cui-reveal-hidden-opacity: 0;
  }

  :where([data-control-family="reveal"][data-slot="content"]) {
    transition-property: opacity;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
  }

  @media (hover: hover) and (pointer: fine) {
    :where(
        [data-control-family="reveal"][data-slot="scope"]:not(:hover, :focus-within, :has([data-popup-open]))
          [data-control-family="reveal"][data-slot="content"]
      ) {
      opacity: var(--cui-reveal-hidden-opacity);
    }
  }
}

@property --cui-reveal-hidden-opacity {
  syntax: "<number>";
  inherits: true;
  initial-value: 1;
}

"use client";

import { useRender } from "@base-ui/react/use-render";
import type { ComponentProps, CSSProperties } from "react";
import type { RenderProp } from "@/components/control-ui/control-props";
import type { RevealKnobStyle } from "@/components/control-ui/knob-contracts/reveal-knobs";

export type RevealScopeProps = Omit<ComponentProps<"div">, "style"> & {
  render?: RenderProp<ComponentProps<"div">>;
  style?: CSSProperties & RevealKnobStyle;
};

export type RevealProps = Omit<ComponentProps<"span">, "style"> & {
  render?: RenderProp<ComponentProps<"span">>;
  style?: CSSProperties & RevealKnobStyle;
};

export function RevealScope({ render, ...props }: RevealScopeProps) {
  return useRender({
    defaultTagName: "div",
    render,
    props: {
      ...props,
      "data-control-ui": "reveal",
      "data-control-family": "reveal",
      "data-slot": "scope",
    },
  });
}

export function Reveal({ render, ...props }: RevealProps) {
  return useRender({
    defaultTagName: "span",
    render,
    props: {
      ...props,
      "data-control-ui": "reveal",
      "data-control-family": "reveal",
      "data-slot": "content",
    },
  });
}
